1	//! Path (point-sequence) containers.
2	//!
3	//! In the C++ header these are `std::vector` aliases:
4	//!
5	//! ```cpp
6	//! template <typename T> using Path  = std::vector<Point<T>>;
7	//! template <typename T> using Paths = std::vector<Path<T>>;
8	//! using Path64  = Path<int64_t>;
9	//! using Paths64 = Paths<int64_t>;
10	//! ```
11	//!
12	//! `test1.cpp` relies on exactly two vector behaviours: brace-initialisation
13	//! from a point list, and `size()` returning the number of points held. Both are
14	//! reproduced here, with the rest of the vector-like surface delegated to the
15	//! wrapped [`Vec`].
16	
17	use super::point::{PointD, Point64};
18	use super::rect::Rect64;
19	use std::fmt;
20	use std::ops::{Deref, DerefMut};
21	
22	/// Builds a [`Path64`] from a point list, mirroring C++ brace-initialisation.
23	///
24	/// ```ignore
25	/// // C++: Path64 path = {Point64(0,0), Point64(100,0)};
26	/// let path = path64![(0, 0), (100, 0)];
27	/// ```
28	///
29	/// The expansion names the types as `$crate::Path64` / `$crate::Point64`, i.e.
30	/// through the crate-root re-exports, so it resolves the same whether this file
31	/// is the crate root of the `clipper2` library or is pulled into `test1.rs` as a
32	/// module for the standalone `rustc` build.
33	#[macro_export]
34	macro_rules! path64 {
35	    () => { $crate::Path64::new() };
36	    ($(($x:expr, $y:expr)),+ $(,)?) => {
37	        $crate::Path64::from(vec![$($crate::Point64::new($x, $y)),+])
38	    };
39	    ($($p:expr),+ $(,)?) => {
40	        $crate::Path64::from(vec![$($p),+])
41	    };
42	}
43	
44	/// An ordered sequence of [`Point64`]s — the C++ `Path64`.
45	///
46	/// A newtype over `Vec<Point64>` rather than a bare alias, so that the C++
47	/// spelling of the vector interface (`size`, `empty`, `push_back`, …) can be
48	/// offered verbatim. [`Deref`]/[`DerefMut`] to `Vec<Point64>` keep the whole
49	/// standard vector surface (indexing, iteration, `sort`, …) available too.
50	#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
51	pub struct Path64(Vec<Point64>);
52	
53	impl Path64 {
54	    /// An empty path — the default-constructed `Path64()`.
55	    #[inline]
56	    pub const fn new() -> Self {
57	        Self(Vec::new())
58	    }
59	
60	    /// An empty path with room for `n` points, as `std::vector::reserve` gives.
61	    #[inline]
62	    pub fn with_capacity(n: usize) -> Self {
63	        Self(Vec::with_capacity(n))
64	    }
65	
66	    /// Number of points in the path — the C++ `size()`.
67	    ///
68	    /// This is the single value `test1.cpp` prints, so it is the one result that
69	    /// must match the C++ program byte for byte once formatted.
70	    #[inline]
71	    pub fn size(&self) -> usize {
72	        self.0.len()
73	    }
74	
75	    /// Whether the path holds no points — the C++ `empty()`.
76	    #[inline]
77	    pub fn empty(&self) -> bool {
78	        self.0.is_empty()
79	    }
80	
81	    /// Appends a point — the C++ `push_back()`.
82	    #[inline]
83	    pub fn push_back(&mut self, p: Point64) {
84	        self.0.push(p);
85	    }
86	
87	    /// Borrows the points as a slice.
88	    #[inline]
89	    pub fn points(&self) -> &[Point64] {
90	        &self.0
91	    }
92	
93	    /// Consumes the path, yielding the underlying vector.
94	    #[inline]
95	    pub fn into_vec(self) -> Vec<Point64> {
96	        self.0
97	    }
98	
99	    /// Axis-aligned bounding box, or `None` when the path is empty.
100	    ///
101	    /// `None` is deliberate: the C++ library encodes "no bounds" with a sentinel
102	    /// rectangle, and reproducing that sentinel is not derivable from the public
103	    /// interface, so this crate declines to invent one.
104	    pub fn bounds(&self) -> Option<Rect64> {
105	        Rect64::from_points(&self.0)
106	    }
107	
108	    /// Twice the signed area of the closed polygon described by the path.
109	    ///
110	    /// The doubled value is returned so the shoelace sum stays exact in integer
111	    /// arithmetic; `i128` accumulation means even full-range `i64` coordinates
112	    /// cannot overflow. Positive when the ring winds clockwise on screen (y
113	    /// growing downward), negative when it winds the other way.
114	    pub fn signed_area2(&self) -> i128 {
115	        let n = self.0.len();
116	        if n < 3 {
117	            return 0;
118	        }
119	        let mut acc: i128 = 0;
120	        let mut prev = self.0[n - 1];
121	        for &cur in &self.0 {
122	            acc += prev.x as i128 * cur.y as i128 - cur.x as i128 * prev.y as i128;
123	            prev = cur;
124	        }
125	        acc
126	    }
127	
128	    /// Signed area of the closed polygon, in square units.
129	    #[inline]
130	    pub fn area(&self) -> f64 {
131	        self.signed_area2() as f64 / 2.0
132	    }
133	
134	    /// Widens every coordinate, producing the `PathD` counterpart.
135	    pub fn to_path_d(&self) -> PathD {
136	        PathD::from(self.0.iter().map(|p| p.to_point_d()).collect::<Vec<_>>())
137	    }
138	}
139	
140	impl Deref for Path64 {
141	    type Target = Vec<Point64>;
142	    #[inline]
143	    fn deref(&self) -> &Self::Target {
144	        &self.0
145	    }
146	}
147	
148	impl DerefMut for Path64 {
149	    #[inline]
150	    fn deref_mut(&mut self) -> &mut Self::Target {
151	        &mut self.0
152	    }
153	}
154	
155	impl From<Vec<Point64>> for Path64 {
156	    #[inline]
157	    fn from(points: Vec<Point64>) -> Self {
158	        Self(points)
159	    }
160	}
161	
162	impl From<Path64> for Vec<Point64> {
163	    #[inline]
164	    fn from(path: Path64) -> Self {
165	        path.0
166	    }
167	}
168	
169	impl<const N: usize> From<[Point64; N]> for Path64 {
170	    #[inline]
171	    fn from(points: [Point64; N]) -> Self {
172	        Self(points.to_vec())
173	    }
174	}
175	
176	impl FromIterator<Point64> for Path64 {
177	    #[inline]
178	    fn from_iter<I: IntoIterator<Item = Point64>>(iter: I) -> Self {
179	        Self(iter.into_iter().collect())
180	    }
181	}
182	
183	impl IntoIterator for Path64 {
184	    type Item = Point64;
185	    type IntoIter = std::vec::IntoIter<Point64>;
186	    #[inline]
187	    fn into_iter(self) -> Self::IntoIter {
188	        self.0.into_iter()
189	    }
190	}
191	
192	impl<'a> IntoIterator for &'a Path64 {
193	    type Item = &'a Point64;
194	    type IntoIter = std::slice::Iter<'a, Point64>;
195	    #[inline]
196	    fn into_iter(self) -> Self::IntoIter {
197	        self.0.iter()
198	    }
199	}
200	
201	impl fmt::Display for Path64 {
202	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
203	        for (i, p) in self.0.iter().enumerate() {
204	            if i > 0 {
205	                f.write_str(" ")?;
206	            }
207	            write!(f, "{p}")?;
208	        }
209	        Ok(())
210	    }
211	}
212	
213	/// A sequence of [`Path64`]s — the C++ `Paths64`.
214	#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
215	pub struct Paths64(Vec<Path64>);
216	
217	impl Paths64 {
218	    /// An empty collection.
219	    #[inline]
220	    pub const fn new() -> Self {
221	        Self(Vec::new())
222	    }
223	
224	    /// Number of paths held — the C++ `size()`.
225	    #[inline]
226	    pub fn size(&self) -> usize {
227	        self.0.len()
228	    }
229	
230	    /// Whether no paths are held — the C++ `empty()`.
231	    #[inline]
232	    pub fn empty(&self) -> bool {
233	        self.0.is_empty()
234	    }
235	
236	    /// Appends a path — the C++ `push_back()`.
237	    #[inline]
238	    pub fn push_back(&mut self, path: Path64) {
239	        self.0.push(path);
240	    }
241	
242	    /// Total number of points across every path.
243	    #[inline]
244	    pub fn total_points(&self) -> usize {
245	        self.0.iter().map(Path64::size).sum()
246	    }
247	}
248	
