#[test]
fn sign_convention_screen_clockwise_is_positive() {
    // y grows downward. TL -> TR -> BR -> BL is clockwise on screen.
    let cw = Path64::from(vec![
        Point64::new(0, 0), Point64::new(100, 0), Point64::new(100, 100), Point64::new(0, 100),
