    // Triangle TL -> TR -> BL, clockwise on screen
    let tri = Path64::from(vec![
        Point64::new(0, 0), Point64::new(10, 0), Point64::new(0, 10),
    ]);
    assert_eq!(tri.signed_area2(), 100, "triangle cw");
    assert_eq!(tri.area(), 50.0);
    // Rect64::corners() claims "clockwise from the top-left" -> must be positive
    let r = Rect64::new(0, 0, 100, 100);
    assert_eq!(Path64::from(r.corners()).signed_area2(), 20_000);
    // exactly one closing edge: adding an explicit duplicate of the first point
    // must not change the area
    let mut closed = cw.clone();
    closed.push_back(Point64::new(0, 0));
    assert_eq!(closed.signed_area2(), cw.signed_area2(), "ring closed exactly once");
}

