    // Rotating the vertex list describes the SAME closed ring, so signed_area2
    // must be unchanged. Brute-force over extreme coordinates.
    let vals = [N, -(1i64<<62), -1, 0, 1, 1i64<<62, M];
    let mut bad = 0usize;
    let mut first_example = None;
    for &a in &vals { for &b in &vals { for &c in &vals { for &d in &vals {
